mapper.select:
SELECT cap.* FROM customer_agreement_price cap WHERE cap.deleted = FALSE AND cap.customer_id = #{query.customerId} AND cap.sku_id = #{query.skuId}
AND ( CAST(cap.sku_id AS TEXT) ILIKE CONCAT('%', #{query.keyword}, '%') OR EXISTS ( SELECT 1 FROM customer c WHERE c.id = cap.customer_id AND c.deleted = FALSE AND (c.customer_code ILIKE CONCAT('%', #{query.keyword}, '%') OR c.name ILIKE CONCAT('%', #{query.keyword}, '%')) ) OR EXISTS ( SELECT 1 FROM product_sku sku JOIN product_spu spu ON spu.id = sku.spu_id AND spu.deleted = FALSE WHERE sku.id = cap.sku_id AND sku.deleted = FALSE AND (sku.sku_code ILIKE CONCAT('%', #{query.keyword}, '%') OR spu.name ILIKE CONCAT('%', #{query.keyword}, '%')) ) )
ORDER BY cap.effective_from DESC, cap.id DESC
